{
  "statements": [
    {
      "id": "3.4.11a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not pass\")",
      "text": "a driver SHOULD NOT pass a vehicle WHEN the vehicle is stopped at a crosswalk BECAUSE a stopped vehicle may be a clue that a pedestrian is crossing",
      "sources": [
        {
          "id": "m76",
          "quote": "Do not pass a vehicle stopped at a crosswalk. A stopped vehicle may be a clue that a pedestrian is crossing."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.4a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"can use\")",
      "text": "a cyclist MAY use any part of the lane WHEN necessary for safety",
      "sources": [
        {
          "id": "m54",
          "quote": "However, they can use any part of the lane if necessary for safety, such as to:"
        }
      ],
      "flags": [],
      "links": [],
      "note": "The lead sentence ends with a colon and lists reasons; the permission itself is in the lead. The specific reason in m55 is handled in 3.4.4b."
    },
    {
      "id": "3.4.4b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "implied (\"Discourage passing\")",
      "text": "a cyclist SHOULD position the bicycle in the lane to discourage passing WHEN the lane is too narrow to be shared safely",
      "sources": [
        {
          "id": "m54",
          "quote": "However, they can use any part of the lane if necessary for safety, such as to:"
        },
        {
          "id": "m55",
          "quote": "Discourage passing where the lane is too narrow to be shared safely"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "too narrow to be shared safely",
          "note": "Subjective judgment of lane width and safety."
        }
      ],
      "links": [
        "3.4.4a"
      ],
      "note": "The item is an infinitive phrase explaining the purpose of using the lane. It is treated as advice for the cyclist to discourage passing."
    },
    {
      "id": "3.4.4c",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must maintain\")",
      "text": "a driver MUST maintain a minimum distance of 1 m between the vehicle and the cyclist WHILE passing a cyclist ONLY IF practical IF VIOLATED a fine AND 2 demerit points",
      "sources": [
        {
          "id": "m56",
          "quote": "When passing a cyclist, drivers of motor vehicles must maintain a minimum distance of one metre, where practical between their vehicle and the cyclist."
        },
        {
          "id": "m57",
          "quote": "(See Diagram 2-11.) Failure to do so may result in a fine and an additional two demerit points on the driver’s record."
        },
        {
          "id": "m59",
          "quote": "bike lane adjacent to parking bays"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "practical",
          "note": "Subjective judgment of what is practical."
        }
      ],
      "links": [],
      "note": "The penalty is in m57. The figure m59 is cited as it is referenced in the penalty sentence."
    },
    {
      "id": "3.4.4d",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"should change lanes\")",
      "text": "a driver SHOULD change lanes to pass a cyclist WHEN possible",
      "sources": [
        {
          "id": "m58",
          "quote": "Whenever possible, you should change lanes to pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "possible",
          "note": "Subjective judgment of possibility."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.4e",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not sound\")",
      "text": "a driver SHOULD NOT sound the horn unnecessarily WHILE passing a cyclist BECAUSE it may frighten the cyclist and cause the cyclist to lose control",
      "sources": [
        {
          "id": "m60",
          "quote": "Do not sound your horn unnecessarily when you are overtaking a cyclist. It may frighten them and cause them to lose control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "unnecessarily",
          "note": "Subjective judgment of necessity."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.4f",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"tap it quickly\")",
      "text": "a driver SHOULD tap the horn quickly and lightly WHILE passing a cyclist WHEN the driver is still some distance away from the cyclist",
      "sources": [
        {
          "id": "m60",
          "quote": "If you feel that you must use your horn, tap it quickly and lightly while you are still some distance away from the cyclist."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "some distance",
          "note": "Vague distance."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"look behind you\")",
      "text": "a driver SHOULD look behind the vehicle AND check the mirrors and blind spots for a passing cyclist WHEN the vehicle is parked on the side of the roadway AND the driver is about to open a door",
      "sources": [
        {
          "id": "m96",
          "quote": "When parked on the side of the roadway, look behind you and check your mirrors and blind spots for a passing cyclist before opening a door."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.6a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not cut in front\")",
      "text": "a driver SHOULD NOT cut in front closely of a large vehicle WHILE passing a large vehicle BECAUSE it reduces the space cushion large vehicles require in order to stop safely",
      "sources": [
        {
          "id": "m65",
          "quote": "When passing a large vehicle, do not cut in front closely. Not only is this discourteous, it is dangerous; it reduces the space cushion large vehicles require in order to stop safely."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "closely",
          "note": "Vague degree of closeness."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.6b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Allow more room\")",
      "text": "a driver SHOULD allow more room WHILE passing a large vehicle",
      "sources": [
        {
          "id": "m65",
          "quote": "Allow more room when passing a large vehicle."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more room",
          "note": "Vague amount of room."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.6c",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a large vehicle can create heavy air turbulence that may affect the driver's ability to control the vehicle WHILE passing a large vehicle",
      "sources": [
        {
          "id": "m66",
          "quote": "6. Turbulence - Due to various factors such as air pressure and airflow, a large vehicle can create heavy air turbulence. This may affect your ability to control your vehicle when passing a large one."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.7a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Stay well back\")",
      "text": "a driver SHOULD stay well back from farm machinery UNTIL it is [?safe] to pass",
      "sources": [
        {
          "id": "m69",
          "quote": "Stay well back and do not pass until it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "well back",
          "note": "Vague distance."
        },
        {
          "code": "J",
          "span": "safe",
          "note": "Subjective judgment of safety."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.7b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not pass\")",
      "text": "a driver SHOULD NOT pass farm machinery UNTIL it is [?safe] to do so",
      "sources": [
        {
          "id": "m69",
          "quote": "Stay well back and do not pass until it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "Subjective judgment of safety."
        }
      ],
