    },
    {
      "id": "3.4.8a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Maintain\")",
      "text": "a driver SHOULD maintain a [?safe] following distance from a horse-drawn vehicle",
      "sources": [
        {
          "id": "m70",
          "quote": "Maintain a safe following distance and only pass when it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "Subjective judgment of safety."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.8b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"pass\")",
      "text": "a driver SHOULD pass a horse-drawn vehicle ONLY IF it is [?safe] to do so",
      "sources": [
        {
          "id": "m70",
          "quote": "Maintain a safe following distance and only pass when it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "Subjective judgment of safety."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.8c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"give as much distance\")",
      "text": "a driver SHOULD give as much distance between the vehicle and the horse-drawn vehicle as possible WHILE passing a horse-drawn vehicle BECAUSE passing too closely could scare or startle the horse, causing it to change direction suddenly on the roadway",
      "sources": [
        {
          "id": "m71",
          "quote": "When passing, give as much distance between you and them as possible. Passing too closely could scare or startle the horse, causing it to change direction suddenly on the roadway."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "as much distance ... as possible",
          "note": "Vague amount of distance."
        }
      ],
      "links": [],
